// Builds the worksuite-sinhala-tools ONLYOFFICE plugin into plugin/dist/ (or --out <dir>):
// plugin/src as it is, plus scripts/sinhala-core.js, the compiled @worksuite/sinhala-core bundled into
// one function the plugin can also hand to an editor command, and scripts/sinhala-words.js, the word list
// Sinhala input ranks with (wordlist/, see sources.json). Run `npm run build:plugin` (it compiles
// the core first). The output depends only on the sources: no dates, sorted file order, LF endings,
// and dist/files.sha256 lists every file's sha256.
import { createHash } from "node:crypto";
import { cpSync, mkdirSync, readFileSync, readdirSync, rmSync, statSync, writeFileSync } from "node:fs";
import { dirname, join, relative, sep } from "node:path";
import { fileURLToPath } from "node:url";
import { buildWordList, readSources } from "./wordlist.mjs";
import { COMMANDS, ICONS, THEMES, iconTemplate, sourceHash, validateRegistry } from "../plugin/icons/registry.mjs";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const outArg = process.argv.indexOf("--out");
const out = outArg > 0 ? process.argv[outArg + 1] : join(root, "plugin", "dist");
const posix = (p) => p.split(sep).join("/");

function walk(dir) {
  return readdirSync(dir).sort().flatMap((name) => {
    const p = join(dir, name);
    return statSync(p).isDirectory() ? walk(p) : [p];
  });
}

// --- the core, as one factory function ---------------------------------------------------------
const coreDir = join(root, "core");
const corePkg = JSON.parse(readFileSync(join(coreDir, "package.json"), "utf8"));
const distDir = join(coreDir, "dist");
const modules = [];
for (const file of walk(join(distDir, "src")).filter((f) => f.endsWith(".js"))) {
  modules.push([posix(relative(distDir, file)), readFileSync(file, "utf8").replace(/\r\n/g, "\n")]);
}
for (const file of walk(join(coreDir, "profiles")).filter((f) => f.endsWith(".json"))) {
  // profiles are data: embedded as JSON text, parsed at load (and sha256-checked by the core)
  const json = JSON.stringify(JSON.parse(readFileSync(file, "utf8")));
  modules.push([posix(relative(coreDir, file)), "module.exports = JSON.parse(" + JSON.stringify(json) + ");\n"]);
}
const body = modules.map(([id, code]) =>
  `    ${JSON.stringify(id)}: function (module, exports, require) {\n${code.replace(/^\/\/# sourceMappingURL=.*$/m, "")}\n    }`).join(",\n");
const bundle = `/* @worksuite/sinhala-core ${corePkg.version}: generated by sinhala/scripts/build-plugin.mjs from sinhala/core, do not edit. */
function __worksuiteSinhalaFactory() {
  "use strict";
  var defs = {
${body}
  };
  var cache = {};
  function resolve(from, request) {
    var parts = from.split("/").slice(0, -1);
    request.split("/").forEach(function (p) {
      if (p === "..") parts.pop(); else if (p !== ".") parts.push(p);
    });
    var id = parts.join("/");
    if (defs[id]) return id;
    if (defs[id + ".js"]) return id + ".js";
    throw new Error("sinhala-core bundle: no module " + request + " from " + from);
  }
  function load(id) {
    if (cache[id]) return cache[id].exports;
    var module = { exports: {} };
    cache[id] = module;
    defs[id](module, module.exports, function (request) { return load(resolve(id, request)); });
    return module.exports;
  }
  return load("src/index.js");
}
var WorkSuiteSinhala = __worksuiteSinhalaFactory();
`;

// --- the ribbon icons: every command has its own icon, label and tooltip, rendered for both themes ---
const srcDir = join(root, "plugin", "src");
const iconProblems = validateRegistry(COMMANDS, ICONS, (f) => { try { return statSync(join(srcDir, f)).isFile(); } catch { return false; } });
const rendered = JSON.parse(readFileSync(join(root, "plugin", "icons", "rendered.json"), "utf8"));
for (const theme of Object.keys(THEMES)) for (const name of Object.keys(ICONS)) {
  if (rendered[`${theme}/${name}`] !== sourceHash(theme, name)) iconProblems.push(`${theme}/${name}: the PNGs are older than the registry (run node scripts/render-icons.mjs)`);
}
if (iconProblems.length) throw new Error("ribbon icons:\n  " + iconProblems.join("\n  "));
const toolbarItems = COMMANDS.map((c) => ({
  id: c.id, label: c.label, hint: c.hint, group: !!c.group,
  icons: iconTemplate(c.icon), iconsOff: c.iconOff ? iconTemplate(c.iconOff) : undefined
}));

// --- the plugin -------------------------------------------------------------------------------
rmSync(out, { recursive: true, force: true });
mkdirSync(out, { recursive: true });
const src = join(root, "plugin", "src");
cpSync(src, out, { recursive: true });
mkdirSync(join(out, "scripts"), { recursive: true });
writeFileSync(join(out, "scripts", "sinhala-core.js"), bundle);
writeFileSync(join(out, "scripts", "toolbar.js"),
  "/* The Sinhala Tools ribbon: generated by sinhala/scripts/build-plugin.mjs from plugin/icons/registry.mjs, do not edit. */\n" +
  "var WorkSuiteSinhalaToolbar = {\n  fallback: " + JSON.stringify(iconTemplate("fallback")) + ",\n  items: [\n" +
  toolbarItems.map((i) => "    " + JSON.stringify(i)).join(",\n") + "\n  ]\n};\n");

// --- the word list for Sinhala input (only the plugin frame loads it, never an editor command) ----
const sources = readSources();
const words = buildWordList();
writeFileSync(join(out, "scripts", "sinhala-words.js"),
  "/* The Sinhala input word list, most frequent first: generated by sinhala/scripts/build-plugin.mjs from\n" +
  sources.map((l) => " * " + l.name + " (" + l.licence + ")" + (l.source.startsWith("http") ? ", " + l.source : "") + (l.attribution ? ". " + l.attribution : "")).join("\n") +
  "\n * See licenses/ for the licence texts. Do not edit. */\nvar WorkSuiteSinhalaWords = " + JSON.stringify(words).replace(/","/g, "\",\n\"") + ";\n");
mkdirSync(join(out, "licenses"), { recursive: true });
cpSync(join(root, "plugin", "icons", "LICENSE-lucide.txt"), join(out, "licenses", "lucide-icons-ISC.txt"));
cpSync(join(root, "wordlist", "slwdc-LICENSE.txt"), join(out, "licenses", "slwdc-Sinhala-Words-List-GPL-3.0.txt"));
writeFileSync(join(out, "licenses", "word-lists.json"), JSON.stringify(sources, null, 2) + "\n");

const config = JSON.parse(readFileSync(join(out, "config.json"), "utf8"));
if (!/^asc\.\{[0-9A-F]{8}-[0-9A-F]{4}-[0-9A-F]{4}-[0-9A-F]{4}-[0-9A-F]{12}\}$/.test(config.guid)) {
  throw new Error("config.json guid must be asc.{GUID}");
}
const manifest = walk(out).filter((f) => !f.endsWith("files.sha256")).map((f) =>
  `${createHash("sha256").update(readFileSync(f)).digest("hex")}  ${posix(relative(out, f))}`);
writeFileSync(join(out, "files.sha256"), manifest.join("\n") + "\n");
console.log(`${config.name} ${config.version} (${config.guid}) in ${out}: ${manifest.length} files`);
